# Let's manually examine the differences
inputs = ['iwbkx', 'kfhgdk', 'gkyg', 'dayyx', 'bdv']
outputs = ['iwveixhx', 'eixhfhgzkeixh', 'geixhyg', 'zkayyx', 'vzkv']

# Looking at each transformation
for i in range(len(inputs)):
    inp = inputs[i]
    outp = outputs[i]
    print(f"Example {i}: '{inp}' -> '{outp}'")

    # Find where they differ
    diff_positions = []
    for j in range(min(len(inp), len(outp))):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    if len(outp) > len(inp):
        # Extra characters at the end
        for j in range(len(inp), len(outp)):
            diff_positions.append((j, '_', outp[j]))
    elif len(inp) > len(outp):
        # Missing characters at the end  
        for j in range(len(outp), len(inp)):
            diff_positions.append((j, inp[j], '_'))

    print(f"  Differences: {diff_positions}")
    print()

